import os,re,signal,subprocess,tempfile,time

def run_branches(jobs,parallelism=2,fail_fast=True,timeout=5):
    if type(parallelism) is not int or not 1<=parallelism<=8 or type(fail_fast) is not bool:
        raise ValueError("invalid execution policy")
    if type(timeout) not in (int,float) or not 0<timeout<=30:
        raise ValueError("invalid timeout")
    if not isinstance(jobs,list) or not 1<=len(jobs)<=16:
        raise ValueError("invalid branches")
    ids=set()
    for job in jobs:
        if not isinstance(job,dict) or set(job)!={"id","argv"}:
            raise ValueError("invalid branch")
        name,argv=job["id"],job["argv"]
        if not isinstance(name,str) or not re.fullmatch(r"[a-zA-Z0-9_-]{1,40}",name) or name in ids:
            raise ValueError("duplicate/invalid identity")
        if not isinstance(argv,list) or not 1<=len(argv)<=32 or any(not isinstance(a,str) or "\x00" in a for a in argv) or not argv[0]:
            raise ValueError("invalid argv")
        ids.add(name)
    results={job["id"]:{"id":job["id"],"state":"not_started","returncode":None,"stdout":"","stderr":"","reason":None} for job in jobs}
    active={}
    cursor=0
    deadline=time.monotonic()+timeout
    stop_reason=None
    def kill_group(process,sig):
        try:os.killpg(process.pid,sig)
        except ProcessLookupError:pass
    def finish(name,reason=None):
        process,out,err=active.pop(name)
        rc=process.wait(timeout=1)
        out.seek(0);err.seek(0)
        results[name].update(state="aborted" if reason else ("success" if rc==0 else "failed"),
            returncode=rc,stdout=out.read().decode("utf8","replace"),stderr=err.read().decode("utf8","replace"),reason=reason)
        out.close();err.close()
    def cancel(reason):
        for process,_,_ in active.values():kill_group(process,signal.SIGTERM)
        until=time.monotonic()+0.08
        while time.monotonic()<until and any(p.poll() is None for p,_,_ in active.values()):time.sleep(0.005)
        # Kill the owned group even if its leader already exited; descendants may ignore TERM.
        for process,_,_ in active.values():kill_group(process,signal.SIGKILL)
        for name in list(active):finish(name,reason)
    try:
        while cursor<len(jobs) or active:
            # Observe all natural completions before classifying any cancellation.
            for name,(process,_,_) in list(active.items()):
                if process.poll() is not None:
                    kill_group(process,signal.SIGKILL)
                    finish(name)
            if fail_fast and any(row["state"]=="failed" for row in results.values()):
                stop_reason="peer_failed"
            if time.monotonic()>=deadline and (cursor<len(jobs) or active):
                stop_reason=stop_reason or "timeout"
            if stop_reason:
                cancel(stop_reason)
                for row in results.values():
                    if row["state"]=="not_started":row["reason"]=stop_reason
                break
            while cursor<len(jobs) and len(active)<parallelism:
                job=jobs[cursor];cursor+=1
                out=tempfile.TemporaryFile();err=tempfile.TemporaryFile()
                try:
                    process=subprocess.Popen(job["argv"],stdin=subprocess.DEVNULL,stdout=out,stderr=err,start_new_session=True,shell=False)
                except OSError as exc:
                    out.close();err.close()
                    results[job["id"]].update(state="failed",reason="spawn_error",stderr=type(exc).__name__)
                    if fail_fast:stop_reason="peer_failed";break
                else:active[job["id"]]=(process,out,err)
            if not stop_reason:time.sleep(0.005)
        status="timed_out" if stop_reason=="timeout" else ("failed" if any(r["state"]=="failed" for r in results.values()) else "success")
        return {"status":status,"branches":[results[job["id"]] for job in jobs]}
    finally:
        if active:cancel("supervisor_error")
